// ❌ 요청 시작에 잡고 외부 호출까지 끝까지 들고 있는다
const conn = await pool.connect();
const user = await conn.query('SELECT ...');
const ext = await fetch('https://api...');   // 수백 ms. 연결 쥔 채!
await conn.query('UPDATE ...');
conn.release();

// ✅ DB 작업만 잡고 바로 반납, 외부 호출은 그 사이 연결 없이
const user = await pool.query('SELECT ...');   // 빌리고 즉시 반납
const ext = await fetch('https://api...');      // 연결 안 쥠
await pool.query('UPDATE ...');

{
  max: 10,                       // 풀 크기
  connectionTimeoutMillis: 3000, // 연결 못 얻으면 3초 후 실패 (매달림 방지)
  idleTimeoutMillis: 30000,      // 30초 놀면 연결 정리 (유휴 자원 회수)
  maxLifetimeSeconds: 1800,      // 30분마다 연결 교체 (DB측 누수, 부하 분산)
  // + statement/query timeout (db-lock 7장) 도 함께
}

// ❌ 에러가 나면 release 를 못 한다
const conn = await pool.connect();
const r = await conn.query('...');   // 여기서 throw 되면 -> 누수
conn.release();

// ✅ finally 로 반드시 반납 (또는 pool.query / 자동 반납 헬퍼)
const conn = await pool.connect();
try {
  return await conn.query('...');
} finally {
  conn.release();   // 성공, 실패 무관 항상
}
